scwin.subtotalTargetColumnView = function(tci) {
	return tci;
};

scwin.gridView1_subtotalStyleFormatter = function(value, formattedValue, subtotalColumnId) {
	var subStyle = "";
	if (subtotalColumnId == "column46" && Number(value) > 100) {
		subStyle = "txtRed";
	}
	return subStyle;
};
